    res.status(401).json({
      success: false,
      message: 'Invalid credentials'
    });
  }
});

app.post('/api/auth/register', (req, res) => {
  const { email, password, firstName, lastName } = req.body;

  if (email && password && firstName && lastName) {
    req.session.userId = 'demo-user';
    req.session.user = {
      id: 'demo-user',
