        'X-MSMail-Priority': 'High',
        'Importance': 'high',
        'Reply-To': process.env.EMAIL_FROM || 'nedaxerinvestments.com@zohomail.com',
        'Organization': 'Nedaxer Inc',
        'Message-ID': `<${Date.now()}-${Math.random().toString(36).substr(2, 9)}@nedaxer.com>`
