      }
    },
    {
      name: 'CurrencyLayer',
      priority: 6,
      fetchRates: async () => {
        try {
          const response = await axios.get('http://api.currencylayer.com/live?access_key=FREE_ACCESS_KEY&source=USD', {
            timeout: 10000
          });
          if (response.data.success && response.data.quotes) {
            const rates: { [key: string]: number } = {};
