// Shared types for the application
// This file provides compatibility between MongoDB and PostgreSQL schemas

export interface User {
  _id?: string;
  id?: string;
  uid: string;
  username: string;
  email: string;
  firstName: string;
  lastName: string;
  profilePicture?: string;
  isVerified: boolean;
  isAdmin: boolean;
  balance: number;
  kycStatus?: string;
  transferAccess?: boolean;
  withdrawalAccess?: boolean;
  requiresDeposit?: boolean;
  createdAt: Date;
}

export interface DepositTransaction {
  _id?: string;
  id?: string;
  userId: string;
  adminId: string;
  cryptoSymbol: string;
  cryptoName: string;
  chainType: string;
  networkName: string;
  usdAmount: number;
  cryptoAmount: number;
  cryptoPrice: number;
  createdAt: Date;
}

export interface WithdrawalTransaction {
  _id?: string;
  id?: string;
  userId: string;
  adminId: string;
  cryptoSymbol: string;
  cryptoName: string;
  chainType: string;
  networkName: string;
  withdrawalAddress: string;
  usdAmount: number;
  cryptoAmount: number;
  cryptoPrice: number;
  createdAt: Date;
}

export interface Transfer {
  _id?: string;
  id?: string;
  senderUserId: string;
