const { Schema, model } = mongoose;

// Interface representing a StakingRate document
export interface IStakingRate extends Document {
  currencyId: string;
  rate: number;  // Annual rate (0.05 = 5%)
  minAmount: number;
  isActive: boolean;
  createdAt: Date;
  updatedAt: Date;
}

// Create the schema
const stakingRateSchema = new Schema<IStakingRate>(
  {
    currencyId: {
      type: String,
      required: true,
      unique: true,
    },
    rate: {
      type: Number,
      required: true,
      min: 0,
      max: 1, // Rate between 0 and 1 (0% to 100%)
    },
    minAmount: {
      type: Number,
      required: true,
      min: 0,
    },
    isActive: {
      type: Boolean,
      default: true,
    },
    createdAt: {
      type: Date,
      default: Date.now,
    },
    updatedAt: {
      type: Date,
      default: Date.now,
    },
  },
  {
    timestamps: true,
  }
);

// Export the StakingRate model (ensuring it's only defined once)
export const StakingRate = mongoose.models.StakingRate || model<IStakingRate>('StakingRate', stakingRateSchema);

server/models/Transaction.ts.content:
import mongoose, { Document, Schema, model } from 'mongoose';

export interface ITransaction extends Document {
  userId: mongoose.Types.ObjectId;
  type: string; // 'buy', 'sell', 'deposit', 'withdrawal', 'staking', 'unstaking', 'credit'
  sourceId: string; // Currency ID or staking ID (depending on transaction type)
  sourceAmount: number;
  targetId: string; // Currency ID (if applicable)
  targetAmount: number;
  fee: number;
  status: string; // 'pending', 'completed', 'failed'
  txHash?: string; // Blockchain transaction hash (for deposit/withdrawal)
  metadata?: Record<string, any>; // Additional data like price or rate
  createdAt: Date;
}

const transactionSchema = new Schema(
  {
    userId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'User',
      required: true,
    },
    type: {
      type: String,
      enum: ['trade_buy', 'trade_sell', 'deposit', 'withdrawal', 'staking', 'unstaking', 'credit'],
      required: true,
    },
    sourceId: {
      type: mongoose.Schema.Types.ObjectId,
      required: true,
    },
    sourceAmount: {
      type: Number,
      required: true,
    },
    targetId: {
      type: mongoose.Schema.Types.ObjectId,
      required: false,
    },
    targetAmount: {
      type: Number,
      required: false,
    },
    fee: {
      type: Number,
      default: 0,
    },
    status: {
      type: String,
      enum: ['pending', 'completed', 'failed'],
      default: 'completed',
    },
    txHash: {
      type: String,
    },
    metadata: {
      type: Schema.Types.Mixed, // Can store any JSON data
    },
    createdAt: {
      type: Date,
      default: Date.now,
    },
  },
  {
    timestamps: true,
  }
);

// Create indexes for common queries
transactionSchema.index({ userId: 1, createdAt: -1 }); // For user transaction history
transactionSchema.index({ type: 1, status: 1 }); // For filtering by type and status
transactionSchema.index({ txHash: 1 }, { sparse: true }); // For looking up blockchain transactions

// Export the Transaction model
export const Transaction = mongoose.models.Transaction || model<ITransaction>('Transaction', transactionSchema);

