import { ArrowLeft, Copy, Save, Info } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { useEffect, useState } from 'react';
import QRCode from 'qrcode';
import CryptoLogo from '@/components/crypto-logo';

interface AddressDisplayProps {
  onBack: () => void;
  selectedCrypto: string;
  selectedChain: string;
}

const addresses = {
  'USDT': {
    'ERC20': '0x126975caaf44D603307a95E2d2670F6Ef46e563C',
    'TRC20': 'THA5iGZk9mBq5742scd9NsvqAPiJcgt4QL',
    'BSC(BEP-20)': '0x126975caaf44D603307a95E2d2670F6Ef46e563C'
  },
  'BTC': {
    'BTC': 'bc1qq35fj5pxkwflsrlt4xk8jta5wx22qy4knnt2q2'
  },
  'ETH': {
    'ETH': '0xDD843A736960D0dd2508c02389AF61970D2a6185',
    'ETH(BEP-20)': '0x126975caaf44D603307a95E2d2670F6Ef46e563C'
  },
  'BEP-20': {
    'BEP-20': '0x126975caaf44D603307a95E2d2670F6Ef46e563C'
  }
};

const minimumAmounts = {
  'USDT': '0.000006',
  'BTC': '0.000006',
  'ETH': '0.00001',
  'BEP-20': '0.0001'
};

export function AddressDisplay({ onBack, selectedCrypto, selectedChain }: AddressDisplayProps) {
  const [qrCodeUrl, setQrCodeUrl] = useState('');
  const [copied, setCopied] = useState(false);

  const address = addresses[selectedCrypto as keyof typeof addresses]?.[selectedChain as keyof typeof addresses[keyof typeof addresses]] || '';
  const minAmount = minimumAmounts[selectedCrypto as keyof typeof minimumAmounts] || '0.000001';

  useEffect(() => {
    if (address) {
      QRCode.toDataURL(address, {
        width: 256,
        margin: 2,
        color: {
          dark: '#000000',
          light: '#FFFFFF'
        }
      }).then(setQrCodeUrl);
    }
  }, [address]);



  const copyAddress = async () => {
    try {
      await navigator.clipboard.writeText(address);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error('Failed to copy address:', err);
    }
  };

  const saveQRCode = () => {
    if (qrCodeUrl) {
      const link = document.createElement('a');
      link.download = `${selectedCrypto}-${selectedChain}-address.png`;
      link.href = qrCodeUrl;
      link.click();
    }
  };

  return (
    <div className="min-h-screen bg-[#0a0a2e] text-white">
      {/* Header */}
      <div className="flex items-center justify-between p-4 bg-[#0a0a2e]">
        <div className="flex items-center space-x-4">
          <button onClick={onBack} className="text-gray-400 hover:text-white">
            <ArrowLeft className="w-6 h-6" />
          </button>
          <div className="flex items-center space-x-2">
            <div className="w-6 h-6 rounded-full overflow-hidden bg-orange-500 flex items-center justify-center">
              <CryptoLogo 
                symbol={selectedCrypto}
                size={16}
                className="w-4 h-4"
              />
            </div>
            <h1 className="text-lg font-semibold">{selectedCrypto}-Deposit</h1>
          </div>
        </div>
        <div className="w-8 h-8 bg-gray-800 rounded-lg flex items-center justify-center">
          <div className="w-4 h-4 grid grid-cols-2 gap-px">
            <div className="bg-gray-400 rounded-sm"></div>
            <div className="bg-gray-400 rounded-sm"></div>
            <div className="bg-gray-400 rounded-sm"></div>
            <div className="bg-gray-400 rounded-sm"></div>
          </div>
        </div>
      </div>

      {/* Network Selection */}
      <div className="px-4 py-2">
        <div className="flex items-center space-x-2">
          <span className="text-gray-400">Network:</span>
          <span className="text-white font-medium">{selectedChain}</span>
          <button className="text-gray-400">
            <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" />
            </svg>
          </button>
        </div>
      </div>

      {/* QR Code */}
      <div className="px-4 py-6">
        <div className="bg-white rounded-lg p-4 mx-auto w-fit">
          {qrCodeUrl ? (
            <div className="relative">
              <img src={qrCodeUrl} alt="QR Code" className="w-64 h-64" />
              <div className="absolute inset-0 flex items-center justify-center">
                <div className="w-8 h-8 bg-orange-500 rounded-full flex items-center justify-center">
                  <CryptoLogo 
                    symbol={selectedCrypto}
                    size={20}
                    className="w-5 h-5"
                  />
                </div>
              </div>
            </div>
          ) : (
            <div className="w-64 h-64 bg-gray-200 animate-pulse rounded"></div>
          )}
        </div>
      </div>

      {/* Address Section */}
      <div className="px-4 space-y-4">
        <div className="bg-gray-800 rounded-lg p-4">
          <div className="flex items-center justify-between mb-2">
            <span className="text-gray-400">Wallet Address</span>
            <button className="text-gray-400">
              <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20">
                <path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" />
              </svg>
            </button>
          </div>
          <div className="flex items-center justify-between">
            <span className="text-white font-mono text-sm break-all">{address}</span>
            <button 
              onClick={copyAddress}
              className="ml-3 p-2 bg-gray-700 rounded hover:bg-gray-600 transition-colors"
            >
              <Copy className="w-4 h-4 text-gray-400" />
            </button>
          </div>
        </div>

        {/* Details */}
        <div className="space-y-3 text-sm">
          <div className="flex justify-between">
            <div className="flex items-center space-x-2">
              <span className="text-gray-400">Minimum Deposit Amount</span>
              <Info className="w-4 h-4 text-gray-400" />
            </div>
            <span className="text-white">{minAmount} {selectedCrypto}</span>
          </div>

          <div className="flex justify-between">
            <span className="text-gray-400">Route Deposits To</span>
            <div className="flex items-center space-x-1">
              <span className="text-white">Funding Account</span>
              <button className="text-gray-400">
                <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M7.293 14.707a1 1 0 010-1.414L10.586 10 7.293 6.707a1 1 0 011.414-1.414l4 4a1 1 0 010 1.414l-4 4a1 1 0 01-1.414 0z" clipRule="evenodd" />
                </svg>
              </button>
            </div>
          </div>

          <div className="flex justify-between">
            <div className="flex items-center space-x-2">
              <span className="text-gray-400">Deposit Arrival</span>
              <Info className="w-4 h-4 text-gray-400" />
            </div>
            <span className="text-white">1 confirmations</span>
          </div>

          <div className="flex justify-between">
            <div className="flex items-center space-x-2">
              <span className="text-gray-400">Withdrawal Unlocked</span>
              <Info className="w-4 h-4 text-gray-400" />
            </div>
            <span className="text-white">2 confirmations</span>
          </div>
        </div>
      </div>

      {/* Warning */}
      <div className="px-4 py-6">
        <div className="text-xs text-gray-400 space-y-2">
          <p>
            <span className="text-orange-500 underline cursor-pointer">View all deposit and withdrawal statuses?</span>
          </p>
          <p>
            In upholding the integrity and safety of our platform's trading environment, Nedaxer is 
            dedicated to combating financial crime and ensuring adherence to anti-money 
            laundering measures.
          </p>
          <p>
            Please make sure that only {selectedCrypto} deposit is made via this address. Otherwise, your 
            deposited funds will not be added to your available balance — nor will it be refunded.
          </p>
          <p>
            Please make sure that your Nedaxer deposit address is correct. Otherwise, your deposited 
            funds will not be added to your available balance — nor will it be refunded.
          </p>
          {selectedChain.includes('BEP') && (
            <p>BEP2 and BEP20 (BSC) deposits not supported.</p>
          )}
        </div>
      </div>

      {/* Action Buttons */}
      <div className="px-4 pb-8">
        <div className="flex space-x-3">
          <Button 
            onClick={saveQRCode}
            variant="outline" 
            className="flex-1 bg-gray-800 border-gray-600 text-white hover:bg-gray-700"
          >
            <Save className="w-4 h-4 mr-2" />
            Save Picture
          </Button>
          <Button 
            onClick={copyAddress}
            className="flex-1 bg-orange-500 hover:bg-orange-600 text-white"
          >
            <Copy className="w-4 h-4 mr-2" />
            {copied ? 'Copied!' : 'Copy Address'}
          </Button>
        </div>
      </div>
    </div>
  );
}

client/src/components/admin-deposit-crea.content:
import { useState, useEffect } from 'react';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { useMutation, useQueryClient, useQuery } from '@tanstack/react-query';
import { apiRequest } from '@/lib/queryClient';
import { useToast } from '@/hooks/use-toast';
import { Plus, DollarSign, RefreshCw } from 'lucide-react';

interface ChainInfo {
  name: string;
  network: string;
  fee: string;
  time: string;
}

interface Crypto {
  symbol: string;
  name: string;
  chains: ChainInfo[];
}

const cryptocurrencies: Crypto[] = [
  {
    symbol: 'USDT',
    name: 'Tether',
    chains: [
      { name: 'ERC20', network: 'Ethereum Network', fee: '~15 USDT', time: '5-15 min' },
      { name: 'TRC20', network: 'TRON Network', fee: '~1 USDT', time: '1-3 min' },
      { name: 'BSC', network: 'BNB Smart Chain', fee: '~0.5 USDT', time: '1-3 min' },
    ],
  },
  {
    symbol: 'BTC',
    name: 'Bitcoin',
    chains: [
      { name: 'Bitcoin', network: 'Bitcoin Network', fee: '~0.0005 BTC', time: '30-60 min' },
    ],
  },
  {
    symbol: 'ETH',
    name: 'Ethereum',
    chains: [
      { name: 'ETH', network: 'Ethereum Network', fee: '~0.005 ETH', time: '5-15 min' },
      { name: 'ETH (BEP-20)', network: 'BNB Smart Chain', fee: '~0.001 ETH', time: '1-3 min' },
    ],
  },
  {
    symbol: 'BNB',
    name: 'BNB',
    chains: [
      { name: 'BEP-20', network: 'BNB Smart Chain', fee: '~0.001 BNB', time: '1-3 min' },
    ],
  },
];



interface AdminDepositCreatorProps {
  userId: string;
  username: string;
  onSuccess?: () => void;
}

export default function AdminDepositCreator({ userId, username, onSuccess }: AdminDepositCreatorProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [selectedCrypto, setSelectedCrypto] = useState<Crypto | null>(null);
  const [selectedChain, setSelectedChain] = useState<ChainInfo | null>(null);
  const [usdAmount, setUsdAmount] = useState('');
  const [senderAddress, setSenderAddress] = useState('');
  const [cryptoPrices, setCryptoPrices] = useState<{ [key: string]: number }>({});

  const { toast } = useToast();
  const queryClient = useQueryClient();

  // Fetch real-time crypto prices from backend cached endpoint
  const { data: priceData, refetch: refetchPrices } = useQuery({
    queryKey: ['/api/coins'],
    refetchInterval: 30000, // Refresh every 30 seconds
    staleTime: 0, // Always consider data stale to ensure fresh prices
    queryFn: async () => {
      const response = await fetch('/api/coins');
      if (!response.ok) {
        throw new Error('Failed to fetch crypto prices');
      }
      return response.json();
    },
  });

  useEffect(() => {
    if (priceData && (priceData as any).success && (priceData as any).data && Array.isArray((priceData as any).data)) {
      const prices: { [key: string]: number } = {};
      (priceData as any).data.forEach((crypto: any) => {
        if (crypto.symbol && crypto.price) {
          prices[crypto.symbol.toUpperCase()] = crypto.price;
        }
      });
      setCryptoPrices(prices);
    }
  }, [priceData]);

  const createDepositMutation = useMutation({
    mutationFn: async (data: {
      userId: string;
      cryptoSymbol: string;
      cryptoName: string;
      chainType: string;
      networkName: string;
      senderAddress: string;
      usdAmount: number;
      cryptoPrice: number;
    }) => {
      const response = await fetch('/api/admin/deposits/create', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(data),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.message || 'Failed to create deposit');
      }

      return response.json();
    },
    onSuccess: (data) => {
      toast({
        title: "Deposit Created",
        description: data.message,
        variant: "default",
      });
      setIsOpen(false);
      resetForm();
      onSuccess?.();
      queryClient.invalidateQueries({ queryKey: ["/api/admin/users/all"] });
    },
    onError: (error: any) => {
      toast({
        title: "Deposit Failed",
        description: error.message || "Failed to create deposit",
        variant: "destructive",
      });
    },
  });

  const resetForm = () => {
    setSelectedCrypto(null);
    setSelectedChain(null);
    setUsdAmount('');
    setSenderAddress('');
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!selectedCrypto || !selectedChain || !usdAmount || !senderAddress) {
      toast({
        title: "Missing Information",
        description: "Please fill in all required fields",
        variant: "destructive",
      });
      return;
    }

    const usdAmountNum = parseFloat(usdAmount);
    if (isNaN(usdAmountNum) || usdAmountNum <= 0) {
      toast({
        title: "Invalid Amount",
        description: "Please enter a valid USD amount",
        variant: "destructive",
      });
      return;
    }

    const cryptoPrice = cryptoPrices[selectedCrypto.symbol] || 1;

    createDepositMutation.mutate({
      userId,
      cryptoSymbol: selectedCrypto.symbol,
      cryptoName: selectedCrypto.name,
      chainType: selectedChain.name,
      networkName: selectedChain.network,
      senderAddress,
      usdAmount: usdAmountNum,
      cryptoPrice,
    });
  };

  const calculateCryptoAmount = () => {
    if (!selectedCrypto || !usdAmount) return '0';
    const usdAmountNum = parseFloat(usdAmount);
    if (isNaN(usdAmountNum)) return '0';
    const cryptoPrice = cryptoPrices[selectedCrypto.symbol] || 1;
    return (usdAmountNum / cryptoPrice).toFixed(8);
  };

  return (
    <Dialog open={isOpen} onOpenChange={setIsOpen}>
      <DialogTrigger asChild>
        <Button variant="outline" size="sm" className="border-green-500/30 text-green-400 hover:bg-green-500/20">
          <Plus className="w-4 h-4 mr-1" />
          Create Deposit
        </Button>
      </DialogTrigger>
      <DialogContent className="max-w-2xl w-[95vw] max-h-[90vh] overflow-y-auto bg-slate-900 border-slate-700 text-white">
        <DialogHeader>
          <DialogTitle className="flex items-center justify-between">
            <div className="flex items-center space-x-2">
              <DollarSign className="w-5 h-5 text-green-400" />
              <span>Create Deposit Transaction</span>
            </div>
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={() => refetchPrices()}
              className="border-blue-500/30 text-blue-400 hover:bg-blue-500/20"
            >
              <RefreshCw className="w-4 h-4 mr-1" />
              Update Prices
            </Button>
          </DialogTitle>
          <DialogDescription className="text-gray-400">
            Create a deposit transaction for user: <span className="text-white font-medium">{username}</span>
            <br />
            <span className="text-yellow-400 text-sm">Note: This will add funds to user's account and create transaction history</span>
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-6">
          {/* Cryptocurrency Selection */}
          <div className="space-y-2">
            <Label className="text-sm font-medium">Select Cryptocurrency</Label>
            <Select onValueChange={(value) => {
              const crypto = cryptocurrencies.find(c => c.symbol === value);
              setSelectedCrypto(crypto || null);
              setSelectedChain(null);
            }}>
              <SelectTrigger className="bg-slate-800 border-slate-600">
                <SelectValue placeholder="Choose cryptocurrency" />
              </SelectTrigger>
              <SelectContent className="bg-slate-800 border-slate-700">
                {cryptocurrencies.map((crypto) => (
                  <SelectItem key={crypto.symbol} value={crypto.symbol}>
                    <div className="flex items-center space-x-2">
                      <span className="font-mono text-orange-400">{crypto.symbol}</span>
                      <span className="text-gray-400">-</span>
                      <span>{crypto.name}</span>
                      <span className="text-green-400 text-sm font-mono">
                        {cryptoPrices[crypto.symbol] ? 
                          `$${cryptoPrices[crypto.symbol].toLocaleString(undefined, {
                            minimumFractionDigits: 2,
                            maximumFractionDigits: 6
                          })}` : 
                          '⟳'
                        }
                      </span>
                    </div>
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Chain Selection */}
          {selectedCrypto && (
            <div className="space-y-2">
              <Label className="text-sm font-medium">Select Network Chain</Label>
              <Select onValueChange={(value) => {
                const chain = selectedCrypto.chains.find(c => c.name === value);
                setSelectedChain(chain || null);
              }}>
                <SelectTrigger className="bg-slate-800 border-slate-600">
                  <SelectValue placeholder="Choose network chain" />
                </SelectTrigger>
                <SelectContent className="bg-slate-800 border-slate-700">
                  {selectedCrypto.chains.map((chain) => (
                    <SelectItem key={chain.name} value={chain.name}>
                      <div className="flex flex-col">
