          <div className="p-6">
            <DesktopContent page={getCurrentPageType()}>
              {children}
            </DesktopContent>
          </div>
        </main>
      </div>

      {/* Video Chat Bot - Only on Desktop */}
      <VideoChatBot user={user} />
    </div>
  );
}

