          </Button>
          <div>
            <h1 className="text-3xl font-bold text-white flex items-center gap-3">
              <DollarSign className="w-8 h-8 text-green-500" />
              Deposit Details
            </h1>
            <p className="text-gray-400">Transaction information and deposit summary</p>
