              </div>

              <div className="flex items-center justify-center">
                {transaction.status === 'failed' ? (
                  <>
                    <XCircle className="w-5 h-5 text-red-400 mr-2" />
                    <Badge className="bg-red-500/20 text-red-400 border-red-500/30">
