// TypeScript error suppression for development productivity
import { useState, useEffect } from 'react';
import { useLocation } from 'wouter';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { apiRequest } from '@/lib/queryClient';
import { useAuth } from '@/hooks/use-auth';
import { showSuccessBanner, showErrorBanner } from '@/hooks/use-bottom-banner';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { 
  ArrowLeft, 
  User, 
  Mail, 
  Wallet, 
  DollarSign, 
  Send, 
  Shield, 
  Loader2 
} from 'lucide-react';

interface RecipientInfo {
  _id: string;
  uid: string;
  email: string;
  username: string;
  firstName: string;
  lastName: string;
  profilePicture?: string;
}

export default function DesktopTransfer() {
  const { user } = useAuth();
  const [, navigate] = useLocation();
  const queryClient = useQueryClient();

  const [transferAmount, setTransferAmount] = useState('');
  const [recipientIdentifier, setRecipientIdentifier] = useState('');
  const [recipientInfo, setRecipientInfo] = useState<RecipientInfo | null>(null);
  const [isSearching, setIsSearching] = useState(false);
  const [note, setNote] = useState('');
  const [selectedMethod, setSelectedMethod] = useState<'email' | 'uid'>('email');
  const [errors, setErrors] = useState<{ [key: string]: string }>({});

  // Fetch user balance
  const { data: walletData } = useQuery({
    queryKey: ['/api/wallet/summary'],
    enabled: !!user,
  });

  // Check if user requires deposit
  const { data: depositRequirementData } = useQuery({
    queryKey: ['/api/user/deposit-requirement'],
    enabled: !!user,
  });

  // Transfer mutation
  const transferMutation = useMutation({
    mutationFn: async (data: { recipientId: string; amount: number; note?: string }) => {
      return apiRequest('/api/transfer', {
        method: 'POST',
        data,
      });
    },
    onSuccess: (response) => {
      if (response.success) {
        showSuccessBanner(
          'Transfer Successful',
          `Successfully sent $${transferAmount} to ${recipientInfo?.firstName || recipientInfo?.username}`
        );
        // Reset form
        setTransferAmount('');
        setRecipientIdentifier('');
        setRecipientInfo(null);
        setNote('');
        setErrors({});
        // Refresh balance
        queryClient.invalidateQueries({ queryKey: ['/api/wallet/summary'] });
        // Navigate back to assets
        navigate('/mobile/assets');
      } else {
        showErrorBanner(
          'Transfer Failed',
          response.message || 'Unable to process transfer'
        );
      }
    },
    onError: (error: any) => {
      showErrorBanner(
        'Transfer Error',
        error.message || 'An error occurred during transfer'
      );
    }
  });

  // Search for recipient
  const searchRecipient = async (identifier: string) => {
    if (!identifier.trim()) {
      setRecipientInfo(null);
      return;
    }

    setIsSearching(true);
    setErrors({});

    try {
      const response = await apiRequest('/api/search-user', {
        method: 'POST',
        data: {
          identifier: identifier.trim(),
          searchType: selectedMethod
        }
      });

      if (response.success && response.data) {
        setRecipientInfo(response.data);
      } else {
        setRecipientInfo(null);
        setErrors({ recipient: 'User not found' });
      }
    } catch (error: any) {
      setRecipientInfo(null);
      setErrors({ recipient: error.message || 'Error searching for user' });
    } finally {
      setIsSearching(false);
    }
  };

  // Debounced search
  useEffect(() => {
    const timer = setTimeout(() => {
      if (recipientIdentifier.trim()) {
        searchRecipient(recipientIdentifier);
      } else {
        setRecipientInfo(null);
      }
    }, 500);

    return () => clearTimeout(timer);
  }, [recipientIdentifier, selectedMethod]);

  const handleTransfer = () => {
    const newErrors: { [key: string]: string } = {};

    if (!transferAmount || parseFloat(transferAmount) <= 0) {
      newErrors.amount = 'Please enter a valid amount';
    }

    if (!recipientInfo) {
      newErrors.recipient = 'Please select a valid recipient';
    }

    const balance = walletData?.data?.totalBalance || 0;
    if (parseFloat(transferAmount) > balance) {
      newErrors.amount = 'Insufficient balance';
    }

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    // Check if user requires deposit
    if (depositRequirementData?.data?.requiresDeposit) {
      showErrorBanner(
        'Deposit Required',
        'Please make a deposit to enable transfers'
      );
      return;
    }

    transferMutation.mutate({
      recipientId: recipientInfo._id,
      amount: parseFloat(transferAmount),
      note: note.trim() || undefined,
    });
  };

  const getUserUSDBalance = () => {
    return walletData?.data?.totalUSDValue || walletData?.data?.totalBalance || 0;
  };

  const setMaxAmount = () => {
    const balance = getUserUSDBalance();
    setTransferAmount(balance.toString());
  };

  return (
    <div className="space-y-6">

        {/* Balance Card */}
        <Card className="bg-black/20 backdrop-blur-sm border-gray-700/50 mb-8">
          <CardHeader>
            <CardTitle className="text-white flex items-center gap-2">
              <Wallet className="w-5 h-5 text-orange-500" />
              Available Balance
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-3xl font-bold text-orange-500">
              ${getUserUSDBalance().toLocaleString()}
            </div>
            <p className="text-gray-400 text-sm mt-1">USD Balance</p>
          </CardContent>
        </Card>

        {/* Transfer Form */}
        <Card className="bg-black/20 backdrop-blur-sm border-gray-700/50">
          <CardHeader>
            <CardTitle className="text-white">Transfer Details</CardTitle>
          </CardHeader>
          <CardContent className="space-y-6">
            {/* Send Method Selection */}
            <div className="space-y-3">
              <Label className="text-white">Send Method</Label>
              <div className="flex space-x-2">
                <Button
                  variant={selectedMethod === 'email' ? 'default' : 'outline'}
                  className={`flex-1 ${selectedMethod === 'email' ? 'bg-orange-500 hover:bg-orange-600' : 'border-gray-600 text-gray-300'}`}
                  onClick={() => {
                    setSelectedMethod('email');
                    setRecipientIdentifier('');
                    setRecipientInfo(null);
                  }}
                >
                  <Mail className="w-4 h-4 mr-2" />
                  Email
                </Button>
                <Button
                  variant={selectedMethod === 'uid' ? 'default' : 'outline'}
                  className={`flex-1 ${selectedMethod === 'uid' ? 'bg-orange-500 hover:bg-orange-600' : 'border-gray-600 text-gray-300'}`}
                  onClick={() => {
                    setSelectedMethod('uid');
                    setRecipientIdentifier('');
                    setRecipientInfo(null);
                  }}
                >
                  <User className="w-4 h-4 mr-2" />
                  Nedaxer UID
                </Button>
              </div>
            </div>

            {/* Recipient Input */}
            {selectedMethod && (
              <div className="space-y-3">
                <Label className="text-white">
                  {selectedMethod === 'email' ? 'Recipient Email' : 'Recipient UID'}
                </Label>
                <div className="relative">
                  <Input
                    type={selectedMethod === 'email' ? 'email' : 'text'}
                    placeholder={selectedMethod === 'email' ? 'Enter recipient email' : 'Enter recipient UID'}
                    value={recipientIdentifier}
                    onChange={(e) => setRecipientIdentifier(e.target.value)}
                    className="bg-black/20 border-gray-600 text-white placeholder-gray-400 focus:border-orange-500"
                  />
                  {isSearching && (
                    <div className="absolute right-3 top-1/2 transform -translate-y-1/2">
                      <Loader2 className="w-4 h-4 animate-spin text-orange-500" />
                    </div>
                  )}
                </div>
                {errors.recipient && (
                  <p className="text-red-400 text-sm">{errors.recipient}</p>
                )}
              </div>
            )}

            {/* Recipient Info */}
            {recipientInfo && (
              <div className="bg-green-900/20 border border-green-500/30 rounded-lg p-4">
                <div className="flex items-center space-x-3">
                  <div className="w-10 h-10 bg-gradient-to-br from-orange-500 to-red-500 rounded-full flex items-center justify-center">
                    {recipientInfo.profilePicture ? (
                      <img 
                        src={recipientInfo.profilePicture} 
                        alt="Profile" 
                        className="w-full h-full rounded-full object-cover"
                      />
                    ) : (
                      <User className="w-5 h-5 text-white" />
                    )}
                  </div>
                  <div>
                    <p className="text-white font-medium">
                      {recipientInfo.firstName && recipientInfo.lastName
                        ? `${recipientInfo.firstName} ${recipientInfo.lastName}`
                        : recipientInfo.username}
                    </p>
                    <p className="text-gray-400 text-sm">{recipientInfo.email}</p>
                    <p className="text-gray-400 text-sm">UID: {recipientInfo.uid}</p>
                  </div>
                </div>
              </div>
            )}

            {/* Transfer Amount */}
            <div className="space-y-3">
              <Label className="text-white">Transfer Amount (USD)</Label>
              <div className="relative">
                <Input
                  type="number"
                  placeholder="0.00"
                  value={transferAmount}
                  onChange={(e) => setTransferAmount(e.target.value)}
                  className="bg-black/20 border-gray-600 text-white placeholder-gray-400 focus:border-orange-500 pl-8"
                />
                <DollarSign className="w-4 h-4 text-gray-400 absolute left-3 top-1/2 transform -translate-y-1/2" />
                <Button
                  variant="link"
                  size="sm"
                  onClick={setMaxAmount}
                  className="absolute right-2 top-1/2 transform -translate-y-1/2 text-orange-500 hover:text-orange-400 h-auto p-0"
                >
                  Max
                </Button>
              </div>
              {errors.amount && (
                <p className="text-red-400 text-sm">{errors.amount}</p>
              )}
            </div>

            {/* Note (Optional) */}
            <div className="space-y-3">
              <Label className="text-white">Note (Optional)</Label>
              <Textarea
                placeholder="Add a note for this transfer..."
                value={note}
                onChange={(e) => setNote(e.target.value)}
                className="bg-black/20 border-gray-600 text-white placeholder-gray-400 focus:border-orange-500 resize-none"
                rows={3}
              />
            </div>

            {/* Transfer Button */}
            <Button
              onClick={handleTransfer}
              disabled={transferMutation.isPending || !recipientInfo || !transferAmount}
              className="w-full bg-orange-500 hover:bg-orange-600 text-white font-medium py-3"
            >
              {transferMutation.isPending ? (
                <div className="flex items-center justify-center">
                  <Loader2 className="w-4 h-4 animate-spin mr-2" />
                  Processing Transfer...
                </div>
              ) : (
                <div className="flex items-center justify-center">
                  <Send className="w-4 h-4 mr-2" />
                  Send ${transferAmount || '0.00'}
                </div>
              )}
            </Button>

            {/* Transfer Security Info */}
            <div className="bg-blue-900/20 border border-blue-500/30 rounded-lg p-4">
              <div className="flex items-start space-x-3">
                <Shield className="w-5 h-5 text-blue-400 mt-0.5 flex-shrink-0" />
                <div>
                  <h4 className="text-blue-400 font-medium text-sm">Secure Transfer</h4>
                  <p className="text-gray-400 text-xs mt-1">
                    All transfers are processed instantly and securely. Please verify the recipient details before sending.
                  </p>
                </div>
              </div>
            </div>
          </CardContent>
        </Card>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { useLocation } from 'wouter';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useAuth } from '@/hooks/use-auth';
import { apiRequest } from '@/lib/queryClient';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { Progress } from '@/components/ui/progress';
import { Badge } from '@/components/ui/badge';
import { Separator } from '@/components/ui/separator';
import { showSuccessBanner, showErrorBanner } from '@/hooks/use-bottom-banner';
import { 
  ArrowLeft, 
  User, 
  Calendar, 
  FileText, 
  Upload, 
  CheckCircle2, 
  AlertCircle,
  Shield,
  Clock,
  Camera,
  Image,
  X,
  Check,
  Info
} from 'lucide-react';

interface VerificationData {
  hearAboutUs?: string;
  dateOfBirth?: { day: number; month: number; year: number };
  sourceOfIncome?: string;
  annualIncome?: string;
  investmentExperience?: string;
  plannedDeposit?: string;
  investmentGoal?: string;
  documentType?: string;
  documents?: {
    front?: File;
    back?: File;
    single?: File;
  };
}

type VerificationStep = 'info' | 'questionnaire' | 'documents' | 'review';

export default function DesktopVerification() {
  const { user } = useAuth();
  const [, navigate] = useLocation();
  const queryClient = useQueryClient();

  const [currentStep, setCurrentStep] = useState<VerificationStep>('info');
  const [verificationData, setVerificationData] = useState<VerificationData>({});
  const [errors, setErrors] = useState<{ [key: string]: string }>({});

  // Fetch current KYC status
  const { data: kycStatus } = useQuery({
    queryKey: ['/api/verification/status'],
    enabled: !!user,
  });

  // Submit verification mutation
  const submitVerificationMutation = useMutation({
    mutationFn: async (data: VerificationData) => {
      const formData = new FormData();

      // Add non-file data
      Object.keys(data).forEach(key => {
        if (key !== 'documents' && data[key as keyof VerificationData] !== undefined) {
          const value = data[key as keyof VerificationData];
          if (typeof value === 'object') {
            formData.append(key, JSON.stringify(value));
          } else {
            formData.append(key, String(value));
          }
        }
      });

      // Add document files
      if (data.documents) {
        Object.keys(data.documents).forEach(docKey => {
          const file = data.documents![docKey as keyof typeof data.documents];
          if (file) {
            formData.append(`documents[${docKey}]`, file);
          }
        });
      }

      const response = await fetch('/api/verification/submit', {
        method: 'POST',
        credentials: 'include',
        body: formData,
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message || 'Failed to submit verification');
      }

      return response.json();
    },
    onSuccess: () => {
      showSuccessBanner(
        'Verification Submitted',
        'Your verification has been submitted successfully and is under review'
      );
      queryClient.invalidateQueries({ queryKey: ['/api/verification/status'] });
      navigate('/mobile/verification-submitted');
    },
    onError: (error: any) => {
      showErrorBanner(
        'Submission Failed',
        error.message || 'Failed to submit verification'
      );
    }
  });

  const updateVerificationData = (key: keyof VerificationData, value: any) => {
    setVerificationData(prev => ({ ...prev, [key]: value }));
    setErrors(prev => ({ ...prev, [key]: '' }));
  };

  const validateStep = (step: VerificationStep): boolean => {
    const newErrors: { [key: string]: string } = {};

    switch (step) {
      case 'info':
        if (!verificationData.hearAboutUs) {
          newErrors.hearAboutUs = 'Please select how you heard about us';
        }
        if (!verificationData.dateOfBirth) {
          newErrors.dateOfBirth = 'Please enter your date of birth';
        }
        break;
      case 'questionnaire':
        if (!verificationData.sourceOfIncome) {
          newErrors.sourceOfIncome = 'Please select your source of income';
        }
        if (!verificationData.annualIncome) {
          newErrors.annualIncome = 'Please select your annual income range';
        }
        if (!verificationData.investmentExperience) {
          newErrors.investmentExperience = 'Please select your investment experience';
        }
        break;
      case 'documents':
        if (!verificationData.documentType) {
          newErrors.documentType = 'Please select a document type';
        }
        if (!verificationData.documents || Object.keys(verificationData.documents).length === 0) {
          newErrors.documents = 'Please upload required documents';
        }
        break;
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleNext = () => {
    if (validateStep(currentStep)) {
      switch (currentStep) {
        case 'info':
          setCurrentStep('questionnaire');
          break;
        case 'questionnaire':
          setCurrentStep('documents');
          break;
        case 'documents':
          setCurrentStep('review');
          break;
        case 'review':
          submitVerificationMutation.mutate(verificationData);
          break;
      }
    }
  };

  const handlePrevious = () => {
    switch (currentStep) {
      case 'questionnaire':
        setCurrentStep('info');
        break;
      case 'documents':
        setCurrentStep('questionnaire');
        break;
      case 'review':
        setCurrentStep('documents');
        break;
    }
  };

  const handleFileUpload = (files: FileList | null, type: 'front' | 'back' | 'single') => {
    if (files && files[0]) {
      const file = files[0];
      if (file.size > 10 * 1024 * 1024) {
        setErrors(prev => ({ ...prev, documents: 'File size must be less than 10MB' }));
        return;
      }

      updateVerificationData('documents', {
        ...verificationData.documents,
        [type]: file
      });
    }
  };

  const getStepProgress = () => {
    switch (currentStep) {
      case 'info': return 25;
      case 'questionnaire': return 50;
      case 'documents': return 75;
      case 'review': return 100;
      default: return 0;
    }
  };

  const currentKycStatus = kycStatus?.data?.kycStatus;
  const isAlreadyVerified = currentKycStatus === 'verified';
  const isPending = currentKycStatus === 'pending';

  return (
    <div className="max-w-4xl mx-auto p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-4">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => navigate('/mobile/profile')}
            className="text-gray-400 hover:text-white"
          >
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back to Profile
          </Button>
          <div>
            <h1 className="text-2xl font-bold text-white">Account Verification</h1>
            <p className="text-gray-400">Complete your identity verification to unlock all features</p>
          </div>
        </div>

        <Card className="bg-black/20 border-gray-700/50">
          <CardContent className="p-4">
            <div className="flex items-center space-x-2">
              <Shield className="w-5 h-5 text-orange-500" />
              <div>
                <p className="text-sm text-gray-400">Verification Status</p>
                <Badge variant={isAlreadyVerified ? 'default' : isPending ? 'secondary' : 'outline'}>
                  {isAlreadyVerified ? 'Verified' : isPending ? 'Under Review' : 'Not Started'}
                </Badge>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Progress Bar */}
      <Card className="bg-black/20 border-gray-700/50">
        <CardContent className="p-4">
          <div className="space-y-2">
            <div className="flex justify-between text-sm">
              <span className="text-gray-400">Verification Progress</span>
              <span className="text-white">{getStepProgress()}%</span>
            </div>
            <Progress value={getStepProgress()} className="h-2" />
            <div className="flex justify-between text-xs text-gray-400">
              <span className={currentStep === 'info' ? 'text-orange-500' : ''}>Personal Info</span>
              <span className={currentStep === 'questionnaire' ? 'text-orange-500' : ''}>Questionnaire</span>
              <span className={currentStep === 'documents' ? 'text-orange-500' : ''}>Documents</span>
              <span className={currentStep === 'review' ? 'text-orange-500' : ''}>Review</span>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Already Verified Message */}
      {isAlreadyVerified && (
        <Card className="bg-green-900/20 border-green-700/50">
          <CardContent className="p-6">
            <div className="flex items-center space-x-3">
              <CheckCircle2 className="w-8 h-8 text-green-500" />
              <div>
                <h3 className="text-white font-semibold text-lg">Account Verified</h3>
                <p className="text-gray-300">Your account has been successfully verified. You have access to all platform features.</p>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Pending Review Message */}
      {isPending && (
        <Card className="bg-blue-900/20 border-blue-700/50">
          <CardContent className="p-6">
            <div className="flex items-center space-x-3">
              <Clock className="w-8 h-8 text-blue-500" />
              <div>
                <h3 className="text-white font-semibold text-lg">Verification Under Review</h3>
                <p className="text-gray-300">Your verification documents are currently being reviewed. This process typically takes 1-2 business days.</p>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Verification Form */}
      {!isAlreadyVerified && !isPending && (
        <div className="grid md:grid-cols-3 gap-6">
          {/* Form Content */}
          <div className="md:col-span-2">
            <Card className="bg-black/20 border-gray-700/50">
              <CardHeader>
                <CardTitle className="text-white">
                  {currentStep === 'info' && 'Personal Information'}
                  {currentStep === 'questionnaire' && 'Investment Profile'}
                  {currentStep === 'documents' && 'Identity Verification'}
                  {currentStep === 'review' && 'Review & Submit'}
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-6">
                {/* Personal Information Step */}
                {currentStep === 'info' && (
                  <div className="space-y-4">
                    <div className="space-y-2">
                      <Label className="text-white">How did you hear about us?</Label>
                      <Select
                        value={verificationData.hearAboutUs || ''}
                        onValueChange={(value) => updateVerificationData('hearAboutUs', value)}
                      >
                        <SelectTrigger className="bg-black/20 border-gray-700/50 text-white">
                          <SelectValue placeholder="Select an option" />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="search">Search Engine</SelectItem>
                          <SelectItem value="social">Social Media</SelectItem>
                          <SelectItem value="friend">Friend Referral</SelectItem>
                          <SelectItem value="ad">Advertisement</SelectItem>
