import { ArrowLeft, Copy, Save, Info } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { useEffect, useState } from 'react';
import QRCode from 'qrcode';
import MobileLayout from '@/components/mobile-layout';
import { useLanguage } from '@/contexts/language-context';
import CryptoLogo from '@/components/crypto-logo';

interface AddressDisplayProps {
  onBack: () => void;
  selectedCrypto: string;
  selectedChain: string;
}

const addresses = {
  'USDT': {
    'ERC20': '0x126975caaf44D603307a95E2d2670F6Ef46e563C',
    'TRC20': 'THA5iGZk9mBq5742scd9NsvqAPiJcgt4QL',
    'BSC': '0x126975caaf44D603307a95E2d2670F6Ef46e563C'
  },
  'BTC': {
    'Bitcoin': 'bc1qq35fj5pxkwflsrlt4xk8jta5wx22qy4knnt2q2'
  },
  'ETH': {
    'ETH': '0xDD843A736960D0dd2508c02389AF61970D2a6185',
    'ETH (BEP-20)': '0x126975caaf44D603307a95E2d2670F6Ef46e563C'
  },
  'BNB': {
    'BEP-20': '0x126975caaf44D603307a95E2d2670F6Ef46e563C'
  }
};

const minimumAmounts = {
  'USDT': '0.000006',
  'BTC': '0.000006',
  'ETH': '0.00001',
  'BNB': '0.0001'
};

export function AddressDisplay({ onBack, selectedCrypto, selectedChain }: AddressDisplayProps) {
  const { t } = useLanguage();
  const [qrCodeUrl, setQrCodeUrl] = useState('');
  const [copied, setCopied] = useState(false);

  const address = addresses[selectedCrypto as keyof typeof addresses]?.[selectedChain as keyof typeof addresses[keyof typeof addresses]] || '';
  const minAmount = minimumAmounts[selectedCrypto as keyof typeof minimumAmounts] || '0.000001';

  useEffect(() => {
    if (address) {
      QRCode.toDataURL(address, {
        width: 200,
        margin: 2,
        color: {
          dark: '#000000',
          light: '#FFFFFF'
        }
      }).then(setQrCodeUrl).catch(console.error);
    }
  }, [address]);



  const copyAddress = async () => {
    try {
      await navigator.clipboard.writeText(address);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error('Failed to copy address:', err);
    }
  };

  const saveQRCode = () => {
    if (qrCodeUrl) {
      const link = document.createElement('a');
      link.href = qrCodeUrl;
      link.download = `${selectedCrypto}_${selectedChain}_address.png`;
      link.click();
    }
  };

  return (
    <div className="min-h-screen bg-[#0a0a2e] text-white">
      {/* Header */}
      <div className="flex items-center justify-between p-4 bg-[#0a0a2e] border-b border-gray-700/30">
        <button onClick={onBack} className="text-gray-400 hover:text-white">
          <ArrowLeft className="w-6 h-6" />
        </button>
        <h2 className="text-base font-semibold text-white">{t('deposit_address')}</h2>
        <div className="w-6 h-6" />
      </div>

      {/* Crypto Info */}
      <div className="p-4 border-b border-gray-700/30 bg-[#0a0a2e]">
        <div className="flex items-center space-x-3 mb-3">
          <div className="w-10 h-10 rounded-full bg-orange-500/20 flex items-center justify-center">
            <CryptoLogo 
              symbol={selectedCrypto}
              size={32}
              className="w-8 h-8"
            />
          </div>
          <div>
            <h3 className="text-white font-semibold text-base">{selectedCrypto}</h3>
            <p className="text-gray-400 text-sm">{selectedChain}</p>
          </div>
        </div>
      </div>

      {/* QR Code */}
      <div className="p-4 bg-[#0a0a2e]">
        <div className="bg-white rounded-xl p-4 mb-4 flex justify-center">
          {qrCodeUrl ? (
            <img 
              src={qrCodeUrl} 
              alt="QR Code" 
              className="w-48 h-48"
            />
          ) : (
            <div className="w-48 h-48 bg-gray-200 rounded-lg flex items-center justify-center">
              <span className="text-gray-500 text-sm">Loading QR Code...</span>
            </div>
          )}
        </div>

        {/* Address */}
        <div className="bg-gray-800/50 rounded-lg p-3 mb-4 border border-gray-700/30">
          <div className="flex items-center justify-between mb-2">
            <span className="text-gray-400 text-xs">Deposit Address</span>
            <button
              onClick={copyAddress}
              className="flex items-center space-x-1 text-orange-500 hover:text-orange-400"
            >
              <Copy className="w-3 h-3" />
              <span className="text-xs">{copied ? 'Copied!' : 'Copy'}</span>
            </button>
          </div>
          <p className="text-white text-xs break-all font-mono">{address}</p>
        </div>

        {/* Action Buttons */}
        <div className="grid grid-cols-2 gap-3 mb-4">
          <Button 
            onClick={copyAddress}
            className="bg-gray-800/50 hover:bg-gray-700/50 text-white text-sm py-2 border border-gray-700/30"
          >
            <Copy className="w-4 h-4 mr-2" />
            {t('copy_address')}
          </Button>
          <Button 
            onClick={saveQRCode}
            className="bg-gray-800/50 hover:bg-gray-700/50 text-white text-sm py-2 border border-gray-700/30"
          >
            <Save className="w-4 h-4 mr-2" />
            {t('save_image')}
          </Button>
        </div>

        {/* Important Info */}
        <div className="bg-yellow-900/20 border border-yellow-700/30 rounded-lg p-3 mb-4">
          <div className="flex items-start space-x-2">
            <Info className="w-4 h-4 text-yellow-500 mt-0.5 flex-shrink-0" />
            <div>
              <p className="text-yellow-200 text-xs font-medium mb-1">Important Notice</p>
              <ul className="text-yellow-100 text-xs space-y-1">
                <li>• Only send {selectedCrypto} to this address</li>
                <li>• Minimum deposit: {minAmount} {selectedCrypto}</li>
                <li>• Sending other tokens may result in permanent loss</li>
                <li>• Network: {selectedChain}</li>
              </ul>
            </div>
          </div>
        </div>

        {/* Network Details */}
        <div className="bg-gray-800/50 rounded-lg p-3 border border-gray-700/30">
          <h4 className="text-white text-sm font-medium mb-2">Network Information</h4>
          <div className="space-y-1">
            <div className="flex justify-between">
              <span className="text-gray-400 text-xs">Network</span>
              <span className="text-white text-xs">{selectedChain}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-gray-400 text-xs">Minimum Deposit</span>
              <span className="text-white text-xs">{minAmount} {selectedCrypto}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-gray-400 text-xs">Expected Confirmations</span>
              <span className="text-white text-xs">
                {selectedChain === 'Bitcoin' ? '3' : selectedChain === 'TRC20' ? '1' : '12'}
              </span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

client/src/pages/mobile/assets-history.t.content:
import { useState, useEffect, useRef } from 'react';
import { Link, useLocation } from 'wouter';
import { ArrowLeft, ChevronRight, CheckCircle, XCircle } from 'lucide-react';
import { Card } from '@/components/ui/card';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { apiRequest } from '@/lib/queryClient';
import { useAuth } from '@/hooks/use-auth';
import AdaptiveLayout from '@/components/adaptive-layout';

// Removed crypto logos as per user request

export default function AssetsHistory() {
  const [activeTab, setActiveTab] = useState('All Transactions');
  const { user } = useAuth();
  const queryClient = useQueryClient();
  const [location] = useLocation();
  const [highlightTransactionId, setHighlightTransactionId] = useState<string | null>(null);
  const transactionRefs = useRef<{ [key: string]: HTMLDivElement | null }>({});

  // Determine back navigation path based on referrer
  const getBackPath = () => {
    // Check if we came from notifications (check URL parameters or localStorage)
    const urlParams = new URLSearchParams(window.location.search);
    const from = urlParams.get('from') || localStorage.getItem('assetsHistoryReferrer') || 'assets';

    if (from === 'notifications') {
      return '/mobile/notifications';
    }
    return '/mobile/assets';
  };

  // Fetch deposit transactions for authenticated user only
  const { data: depositsResponse, isLoading: isLoadingDeposits } = useQuery({
    queryKey: ['/api/deposits/history'],
    enabled: !!user,
    refetchInterval: 30000, // Refresh every 30 seconds for new deposits
    retry: 3,
    retryDelay: 1000,
    staleTime: 0, // Always fetch fresh data
    gcTime: 0, // Don't cache to avoid stale data (replaces cacheTime in newer versions)
    refetchOnMount: 'always', // Always refetch when component mounts
    refetchOnWindowFocus: true, // Refetch when window gains focus
  });

  // Fetch transfer transactions for authenticated user only
  const { data: transfersResponse, isLoading: isLoadingTransfers } = useQuery({
    queryKey: ['/api/transfers/history'],
    enabled: !!user,
    refetchInterval: 30000,
    retry: 3,
    retryDelay: 1000,
    staleTime: 0,
    gcTime: 0,
  });

  // Fetch withdrawal transactions for authenticated user only
  const { data: withdrawalsResponse, isLoading: isLoadingWithdrawals } = useQuery({
    queryKey: ['/api/withdrawals/history'],
    enabled: !!user,
    refetchInterval: 30000,
    retry: 3,
    retryDelay: 1000,
    staleTime: 0,
    gcTime: 0,
  });

  const deposits = Array.isArray((depositsResponse as any)?.data) 
    ? (depositsResponse as any).data.filter((deposit: any) => {
        // Include all deposits with valid amounts, including failed deposits (approved/declined from pending)
        // Don't filter by USD amount for failed deposits as they should still show in history
        if (deposit.status === 'failed') {
          return true; // Always show failed deposits regardless of amount
        }
        // For succeeded deposits, filter out test deposits with very small USD amounts
        return deposit.usdAmount && deposit.usdAmount >= 1 && 
               deposit.cryptoAmount && deposit.cryptoAmount > 0;
      })
    : [];
  const transfers = Array.isArray((transfersResponse as any)?.data) ? (transfersResponse as any).data : [];
  const withdrawals = Array.isArray((withdrawalsResponse as any)?.data) ? (withdrawalsResponse as any).data : [];

  // Debug transaction data for troubleshooting
  console.log('Assets History Debug:', {
    user: user ? { id: (user as any)._id, email: (user as any).email } : null,
    depositsCount: deposits.length,
    transfersCount: transfers.length,
    withdrawalsCount: withdrawals.length,
    firstDeposit: deposits[0] ? {
      id: deposits[0]._id,
      amount: deposits[0].cryptoAmount,
      symbol: deposits[0].cryptoSymbol,
      usdAmount: deposits[0].usdAmount
    } : null,
    firstTransfer: transfers[0] ? {
      id: transfers[0]._id || transfers[0].transactionId,
      amount: transfers[0].amount,
      type: transfers[0].type
    } : null
  });

  // Combine and sort all transactions
  const allTransactions = [...deposits, ...transfers, ...withdrawals].sort((a, b) => 
    new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
  );

  // Filter transactions based on active tab
  const getFilteredTransactions = () => {
    switch(activeTab) {
      case 'All Transactions':
        return allTransactions;
      case 'Deposit':
        // Include both deposits and transfers in deposit mode
        return [...deposits, ...transfers].sort((a, b) => 
          new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
        );
      case 'Transfer':
        return transfers;
      case 'Withdraw':
        return withdrawals;
      default:
        return allTransactions;
    }
  };

  const transactions = getFilteredTransactions();
  const isLoading = isLoadingDeposits || isLoadingTransfers || isLoadingWithdrawals;

  // Force refresh when user changes
  useEffect(() => {
    if (user) {
      queryClient.invalidateQueries({ queryKey: ['/api/deposits/history'] });
      queryClient.invalidateQueries({ queryKey: ['/api/transfers/history'] });
      queryClient.invalidateQueries({ queryKey: ['/api/withdrawals/history'] });
    }
  }, [user, queryClient]);

  // Handle transaction highlighting from sessionStorage
  useEffect(() => {
    const highlightId = sessionStorage.getItem('highlightTransactionId');

    if (highlightId) {
      console.log('🎯 Highlighting transaction:', highlightId);
      setHighlightTransactionId(highlightId);

      // Clear the sessionStorage immediately to prevent re-highlighting on future visits
      sessionStorage.removeItem('highlightTransactionId');

      // Wait for transactions to load and then scroll to highlighted transaction
      const scrollTimer = setTimeout(() => {
        const element = transactionRefs.current[highlightId];
        if (element) {
          element.scrollIntoView({ 
            behavior: 'smooth', 
            block: 'center' 
          });
          console.log('📍 Scrolled to highlighted transaction');
        }
      }, 500);

      // Clear highlight after animation completes (6 seconds)
      const highlightTimer = setTimeout(() => {
        setHighlightTransactionId(null);
        console.log('✨ Transaction highlight animation completed');
      }, 6000);

      return () => {
        clearTimeout(scrollTimer);
        clearTimeout(highlightTimer);
      };
    }
  }, [location, depositsResponse, transfersResponse, withdrawalsResponse]);

  // WebSocket connection for real-time transaction updates
  useEffect(() => {
    let socket: WebSocket;

    const connectWebSocket = () => {
      const protocol = window.location.protocol === "https:" ? "wss:" : "ws:";
      const wsUrl = `${protocol}//${window.location.host}/ws`;
      socket = new WebSocket(wsUrl);

      socket.onopen = () => {
        console.log('WebSocket connected for real-time transaction updates');
        socket.send(JSON.stringify({ type: 'subscribe_notifications' }));
      };

      socket.onmessage = (event) => {
        try {
          const data = JSON.parse(event.data);
          console.log('Real-time transaction update received:', data);

          if (data.type === 'DEPOSIT_CREATED' || data.type === 'TRANSFER_CREATED' || data.type === 'WITHDRAWAL_CREATED') {
            // Refresh transaction history when new deposits, transfers, or withdrawals are created
            queryClient.invalidateQueries({ queryKey: ['/api/deposits/history'] });
            queryClient.invalidateQueries({ queryKey: ['/api/transfers/history'] });
            queryClient.invalidateQueries({ queryKey: ['/api/withdrawals/history'] });
            console.log('Transaction history refreshed due to new transaction');
          }
        } catch (error) {
          console.error('WebSocket message error:', error);
        }
      };

      socket.onclose = () => {
        console.log('WebSocket disconnected, attempting to reconnect...');
        setTimeout(connectWebSocket, 3000);
      };

      socket.onerror = (error) => {
        console.error('WebSocket error:', error);
      };
    };

    if (user) {
      connectWebSocket();
    }

    return () => {
      if (socket) {
        socket.close();
      }
    };
  }, [user, queryClient]);

  // Handle transaction highlighting from URL parameters
  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const highlightId = urlParams.get('highlight');

    if (highlightId && !isLoading && transactions.length > 0) {
      setHighlightTransactionId(highlightId);

      // Wait for DOM to render, then scroll to and highlight the transaction
      setTimeout(() => {
        const transactionElement = transactionRefs.current[highlightId];
        if (transactionElement) {
          // Scroll to the transaction with smooth behavior
          transactionElement.scrollIntoView({ 
            behavior: 'smooth', 
            block: 'center',
            inline: 'nearest'
          });

          // Remove highlight after animation completes
          setTimeout(() => {
            setHighlightTransactionId(null);
            // Clean up URL parameter
            const newUrl = window.location.hash.split('?')[0];
            window.history.replaceState(null, '', newUrl);
          }, 3000);
        }
      }, 500);
    }
  }, [isLoading, transactions.length]);

  const historyTabs = ['All Transactions', 'Deposit', 'Withdraw', 'Transfer'];

  return (
    <AdaptiveLayout title="Nedaxer - Assets History" hideBottomNav={true}>
      <div className="min-h-screen bg-[#0a0a2e] text-white">
        {/* Header */}
        <div className="flex items-center justify-between p-4 bg-[#0a0a2e]">
          <Link href={getBackPath()}>
            <ArrowLeft className="w-6 h-6 text-white" />
          </Link>
          <h1 className="text-base font-medium">Asset History</h1>
          <div className="w-6 h-6" />
        </div>

      {/* Transaction Tabs */}
      <div className="px-4 py-4 bg-[#0a0a2e]">
        <div className="flex space-x-4 overflow-x-auto scrollbar-hide">
          {historyTabs.map((tab) => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`whitespace-nowrap pb-2 px-2 text-xs ${
                activeTab === tab
                  ? 'text-orange-500 border-b-2 border-orange-500'
                  : 'text-gray-400 hover:text-white'
              }`}
            >
              {tab}
            </button>
          ))}
        </div>
      </div>

      {/* Transaction List */}
      <div className="px-4 space-y-3">
        {isLoading ? (
          // Loading skeleton
          <div className="space-y-3">
            {[1, 2, 3].map((i) => (
              <Card key={i} className="bg-[#1a1a40] border-[#2a2a50] p-3 animate-pulse">
                <div className="flex justify-between items-center">
                  <div className="flex-1">
                    <div className="space-y-2">
                      <div className="h-4 bg-gray-700 rounded w-20"></div>
                      <div className="h-3 bg-gray-700 rounded w-16"></div>
                    </div>
                  </div>
                  <div className="text-right space-y-2">
                    <div className="h-4 bg-gray-700 rounded w-16"></div>
                    <div className="h-3 bg-gray-700 rounded w-12"></div>
                  </div>
                </div>
              </Card>
            ))}
          </div>
        ) : transactions.length === 0 ? (
          // Empty state
          <div className="flex flex-col items-center justify-center py-12">
            <div className="w-16 h-16 bg-gray-700 rounded-full flex items-center justify-center mb-4">
              <svg className="w-8 h-8 text-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
              </svg>
            </div>
            <p className="text-gray-400 text-center text-sm">No transaction history</p>
            <p className="text-gray-500 text-xs text-center mt-1">
              Your transactions will appear here
            </p>
          </div>
        ) : (
          // Transaction items
          transactions.map((transaction: any) => {
            // Check if it's a transfer, deposit, or withdrawal
            const isTransfer = transaction.type === 'sent' || transaction.type === 'received';
            const isWithdrawal = transaction.cryptoSymbol && transaction.withdrawalAddress;

            if (isTransfer) {
              const isSent = transaction.type === 'sent';
              const otherUser = isSent ? transaction.toUser : transaction.fromUser;
              const transactionId = transaction.transactionId || transaction._id;
              const isHighlighted =highlightTransactionId === transactionId;

              return (
                <div
                  key={transaction._id}
                  ref={(el) => transactionRefs.current[transactionId] = el}
                  className={`${isHighlighted ? 'transaction-highlight' : ''}`}
                >
                  <Link href={`/mobile/transfer-details/${transaction._id}`}>
                    <Card className="bg-[#1a1a40] border-[#2a2a50] p-3 hover:bg-[#2a2a50] transition-colors cursor-pointer">
                      <div className="flex justify-between items-center">

                        <div className="flex-1">
                          <div className="flex items-center space-x-2">
                            <p className="text-white font-medium text-xs">
                              Transfer
                            </p>
                            <CheckCircle className="w-3 h-3 text-green-500" />
                          </div>
                          <p className="text-gray-400 text-xs">
