import AdaptiveLayout from '@/components/adaptive-layout';
import { Card } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { 
  Search, 
  Star,
  TrendingUp,
  TrendingDown,
  Filter,
  ArrowUpDown,
  RefreshCw,
  Clock
} from 'lucide-react';
import { useState, useEffect } from 'react';
import { useLocation } from 'wouter';
import { useQuery } from '@tanstack/react-query';
import { hapticLight } from '@/lib/haptics';
import { useLanguage } from '@/contexts/language-context';
import { useTheme } from '@/contexts/theme-context';
import { CRYPTO_PAIRS, CryptoPair, getPairDisplayName } from '@/lib/crypto-pairs';
import { useStablePrices } from '@/hooks/use-stable-prices';
import { useOfflineCryptoCache } from '@/hooks/use-offline-crypto-cache';

interface CryptoTicker {
  symbol: string;
  name: string;
  price: number;
  change: number;
  volume: number;
  marketCap: number;
  sentiment: 'Bullish' | 'Bearish' | 'Neutral';
}

interface CoinGeckoResponse {
  success: boolean;
  data: CryptoTicker[];
  timestamp: number;
}

// Helper functions - defined outside component to avoid initialization issues
const formatPrice = (price: number) => {
  if (price >= 1) {
    return price.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 6 });
  }
  return price.toFixed(8);
};

const formatVolume = (volume: number) => {
  if (volume >= 1e9) {
    return `$${(volume / 1e9).toFixed(2)}B`;
  }
  if (volume >= 1e6) {
    return `$${(volume / 1e6).toFixed(2)}M`;
  }
  if (volume >= 1e3) {
    return `$${(volume / 1e3).toFixed(2)}K`;
  }
  return `$${volume.toFixed(2)}`;
};

const getSentimentColor = (sentiment: string) => {
  switch (sentiment) {
    case 'Bullish':
      return 'bg-green-600 text-white';
    case 'Bearish':
      return 'bg-red-600 text-white';
    default:
      return 'bg-gray-600 text-white';
  }
};

const getSentimentIcon = (sentiment: string) => {
  switch (sentiment) {
    case 'Bullish':
      return <TrendingUp className="h-3 w-3" />;
    case 'Bearish':
      return <TrendingDown className="h-3 w-3" />;
    default:
      return <Clock className="h-3 w-3" />;
  }
};

export default function MobileMarkets() {
  const [, navigate] = useLocation();
  const { t } = useLanguage();
  const { getBackgroundClass, getTextClass, getCardClass, getBorderClass } = useTheme();
  const [searchQuery, setSearchQuery] = useState('');
  const [favoriteCoins, setFavoriteCoins] = useState<string[]>([]);
  const [lastUpdate, setLastUpdate] = useState<Date>(new Date());
  const [activeTab, setActiveTab] = useState('Hot');
  const [activeMarketType, setActiveMarketType] = useState('Spot');

  // Load favorites from localStorage
  useEffect(() => {
    const savedFavorites = localStorage.getItem('favoriteCoins');
    if (savedFavorites) {
      setFavoriteCoins(JSON.parse(savedFavorites));
    }
  }, []);

  // Toggle favorite status
  const toggleFavorite = (symbol: string) => {
    hapticLight();
    const newFavorites = favoriteCoins.includes(symbol)
      ? favoriteCoins.filter(id => id !== symbol)
      : [...favoriteCoins, symbol];

    setFavoriteCoins(newFavorites);
    localStorage.setItem('favoriteCoins', JSON.stringify(newFavorites));
  };

  // Use comprehensive offline-capable caching system
  const { 
    cryptoData, 
    isLoading: isCacheLoading, 
    isOffline, 
    cacheStatus, 
    fetchFreshData, 
    forceRefresh 
  } = useOfflineCryptoCache();

  // Transform crypto data to match expected format
  const marketData: CoinGeckoResponse | undefined = cryptoData.length > 0 ? {
    success: true,
    data: cryptoData,
    timestamp: Date.now()
  } : undefined;

  // Update last update time when data changes
  useEffect(() => {
    if (cryptoData.length > 0) {
      setLastUpdate(new Date());
    }
  }, [cryptoData]);

  // Use the offline cache data directly
  const activeMarketData = marketData;
  const isLoading = isCacheLoading;

  // Process comprehensive crypto pairs with live price data
  const processedMarkets = CRYPTO_PAIRS.map((pair: CryptoPair) => {
    // Find matching ticker data from API by base asset (e.g., BTC for BTCUSDT)
    const ticker = activeMarketData?.data?.find((t: CryptoTicker) => t.symbol === pair.baseAsset);

    if (ticker) {
      const price = ticker.price;
      const change = ticker.change;
      const volume = ticker.volume;
      const marketCap = ticker.marketCap;

      // Determine sentiment based on price change
      let sentiment: 'Bullish' | 'Bearish' | 'Neutral' = 'Neutral';
      if (change > 2) sentiment = 'Bullish';
      else if (change < -2) sentiment = 'Bearish';

      return {
        symbol: pair.baseAsset,
        pair: pair.symbol,
        displayPair: getPairDisplayName(pair),
        price: formatPrice(price),
        priceValue: price,
        change: `${change >= 0 ? '+' : ''}${change.toFixed(2)}%`,
        changeValue: change,
        isPositive: change >= 0,
        volume: formatVolume(volume),
        volumeValue: volume,
        high24h: '--',
        low24h: '--',
        sentiment: sentiment,
        favorite: favoriteCoins.includes(pair.symbol),
        cryptoPair: pair
      };
    } else {
      // Return pair with placeholder data for pairs not in live data
      return {
        symbol: pair.baseAsset,
        pair: pair.symbol,
        displayPair: getPairDisplayName(pair),
        price: '0.00',
        priceValue: 0,
        change: '0.00%',
        changeValue: 0,
        isPositive: true,
        volume: '$0',
        volumeValue: 0,
        high24h: '--',
        low24h: '--',
        sentiment: 'Neutral' as const,
        favorite: favoriteCoins.includes(pair.symbol),
        cryptoPair: pair
      };
    }
  });

  // Filter markets based on search query
  const searchFilteredMarkets = processedMarkets.filter(market =>
    market.displayPair.toLowerCase().includes(searchQuery.toLowerCase()) ||
    market.symbol.toLowerCase().includes(searchQuery.toLowerCase())
  );

  // Filter markets based on active tab
  const getFilteredMarkets = () => {
    let filtered = searchFilteredMarkets;

    switch (activeTab) {
      case 'Favorites':
        filtered = filtered.filter(market => market.favorite);
        break;
      case 'Gainers':
        // Filter for positive price changes and sort by highest gains - SHOW ALL
        filtered = filtered.filter(market => market.changeValue > 0)
                          .sort((a, b) => b.changeValue - a.changeValue);
        console.log(`Gainers found: ${filtered.length} out of ${searchFilteredMarkets.length} total markets`);
        break;
      case 'Losers':
        // Filter for negative price changes and sort by biggest losses - SHOW ALL
        filtered = filtered.filter(market => market.changeValue < 0)
                          .sort((a, b) => a.changeValue - b.changeValue);
        break;
      case 'Hot':
        // Sort by volume for hot markets - SHOW ALL
        filtered = filtered.sort((a, b) => b.volumeValue - a.volumeValue);
        break;
      case 'New':
        // Sort by price change for new/trending - top 30
        filtered = filtered.sort((a, b) => Math.abs(b.changeValue) - Math.abs(a.changeValue)).slice(0, 30);
        break;
      default:
        filtered = filtered.sort((a, b) => b.volumeValue - a.volumeValue);
    }

    return filtered;
  };

  const sortedMarkets = getFilteredMarkets();

  const handleCoinClick = (market: any) => {
    hapticLight();
    console.log('Market pair clicked:', market.pair);

    // For hash-based routing, we need to pass parameters differently
    const symbol = market.pair; // Use the full trading pair symbol like BTCUSDT

    // Store the symbol and tab in sessionStorage for the trade page to pick up
    sessionStorage.setItem('selectedSymbol', symbol);
    sessionStorage.setItem('selectedTab', 'Charts');

    console.log('Navigating to trade page with symbol:', symbol);

    // Navigate to trade page - hash routing will handle the base path
    navigate('/mobile/trade');
  };

  return (
    <AdaptiveLayout title="Nedaxer - Markets">
      {/* Search Bar */}
      <div className="p-4 bg-[#0a0a2e]">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-gray-400" />
          <Input 
            placeholder="BDXN/USDT"
            className="pl-10 bg-[#0b0b30] border-[#1a1a40] text-white placeholder-gray-400 rounded-full"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
      </div>

      {/* Top Tabs */}
      <div className="px-4 pb-4">
        <div className="flex space-x-4 overflow-x-auto scrollbar-hide">
          {['Favorites', 'Hot', 'New', 'Gainers', 'Losers'].map((tab) => (
            <button
              key={tab}
              onClick={() => {
                hapticLight();
                setActiveTab(tab);
              }}
              onTouchStart={() => hapticLight()}
              className={`text-sm font-medium whitespace-nowrap transition-colors ${
                activeTab === tab 
                  ? 'text-white border-b-2 border-yellow-500 pb-2' 
                  : 'text-gray-400 hover:text-white pb-2'
              }`}
            >
              {tab}
            </button>
          ))}
        </div>
      </div>



      {/* Cache Status Indicator */}
      <div className="px-4 pb-2">
        <div className="flex items-center justify-between text-xs">
          <div className="flex items-center space-x-2">
            <div className={`w-2 h-2 rounded-full ${
              cacheStatus === 'fresh' ? 'bg-green-500' :
              cacheStatus === 'expired' ? 'bg-yellow-500' :
              cacheStatus === 'offline' ? 'bg-orange-500' : 'bg-gray-500'
            }`} />
            <span className="text-gray-400">
              {cacheStatus === 'fresh' ? 'Live Data' :
               cacheStatus === 'expired' ? 'Cached Data' :
               cacheStatus === 'offline' ? 'Offline Mode' : 'Loading...'}
            </span>
            {isOffline && <span className="text-orange-500">📱 Offline</span>}
          </div>
          <div className="flex items-center space-x-2">
            <button 
              onClick={() => {
                hapticLight();
                fetchFreshData();
              }}
              className="text-blue-400 hover:text-blue-300"
            >
              <RefreshCw className="w-3 h-3" />
            </button>
            <button 
              onClick={() => {
                hapticLight();
                forceRefresh();
              }}
              className="text-yellow-400 hover:text-yellow-300"
              title="Force refresh (keeps trying until successful)"
            >
              <Clock className="w-3 h-3" />
            </button>
          </div>
        </div>
      </div>

      {/* Market List */}
      <div className="px-4 space-y-0 pb-20">
        {isLoading && !marketData ? (
          <div className="text-center py-8">
            <RefreshCw className="w-8 h-8 animate-spin mx-auto mb-2 text-gray-400" />
            <p className="text-gray-400">Loading comprehensive cached data...</p>
            <p className="text-xs text-gray-500 mt-1">
              {cacheStatus === 'fresh' ? 'Fetching live prices' :
               cacheStatus === 'expired' ? 'Using cached prices while fetching fresh data' :
               cacheStatus === 'offline' ? 'Offline mode - using stored data' : 'Initializing cache system'}
            </p>
          </div>
        ) : sortedMarkets.length === 0 ? (
          <div className="text-center py-8">
            <p className="text-gray-400">No markets found.</p>
          </div>
        ) : (
          sortedMarkets.map((market, index) => (
            <div 
              key={`${market.pair}-${index}`} 
              className="flex items-center justify-between py-4 border-b border-blue-800 hover:bg-blue-900/30 cursor-pointer transition-colors"
              onClick={() => handleCoinClick(market)}
              onTouchStart={() => hapticLight()}
            >
              <div className="flex items-center space-x-3">
                <button 
                  onClick={(e) => {
                    e.stopPropagation();
                    toggleFavorite(market.pair);
                  }}
                  className="text-gray-400 hover:text-yellow-500"
                >
                  <Star 
                    className={`w-4 h-4 ${market.favorite ? 'fill-yellow-500 text-yellow-500' : ''}`} 
                  />
                </button>
                <div>
                  <div className="text-white font-medium text-base">{market.displayPair}</div>
                  <div className="text-gray-400 text-sm mt-1">
                    {market.volume}
                  </div>
                </div>
              </div>

              <div className="flex items-center space-x-4">
                <div className="text-right">
                  <div className="text-white font-medium">
                    {market.priceValue > 0 ? `$${market.price}` : '$0.00'}
                  </div>
                  <div className="text-gray-400 text-sm">
                    Vol: {market.volume}
                  </div>
                </div>

                <div className="flex flex-col items-end space-y-1">
                  <div className={`text-right min-w-[80px] px-2 py-1 rounded ${
                    market.isPositive ? 'bg-green-600 text-white' : 'bg-red-600 text-white'
                  }`}>
                    <div className="font-medium text-sm">{market.change}</div>
                  </div>

                  {/* Sentiment Badge */}
                  <div className={`text-xs px-2 py-1 rounded-full flex items-center space-x-1 ${getSentimentColor(market.sentiment)}`}>
                    {getSentimentIcon(market.sentiment)}
                    <span>{market.sentiment}</span>
                  </div>
                </div>
              </div>
            </div>
          ))
        )}
      </div>
    </AdaptiveLayout>
  );
}

client/src/pages/mobile/messages.tsx.content:
import React, { useState, useEffect } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useAuth } from '@/hooks/use-auth';
import { ArrowLeft, MessageSquare, Clock, User, Eye, EyeOff, Reply, AlertCircle } from 'lucide-react';
import { Link } from 'wouter';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import { UserAvatar } from '@/components/user-avatar';
import { ScrollArea } from '@/components/ui/scroll-area';
import { apiRequest } from '@/lib/queryClient';
import { useToast } from '@/hooks/use-toast';

interface ContactMessage {
  _id: string;
  userId: string;
  firstName: string;
  lastName: string;
  email: string;
  subject: string;
  message: string;
  category: string;
  priority: string;
  isRead: boolean;
  hasReply: boolean;
  adminReply?: string;
  adminReplyAt?: string;
  createdAt: string;
  updatedAt: string;
  user?: {
    profilePicture?: string;
    username?: string;
  };
}

export default function MessagesPage() {
  const { user } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [selectedMessage, setSelectedMessage] = useState<ContactMessage | null>(null);

  // Fetch user's contact messages
  const { data: messagesResponse, isLoading } = useQuery<{ success: boolean; data: ContactMessage[] }>({
    queryKey: ['/api/user/contact-messages'],
    enabled: !!user,
  });

  const messages = messagesResponse?.data || [];

  // Mark message as read mutation
  const markAsReadMutation = useMutation({
    mutationFn: async (messageId: string) => {
      const response = await fetch(`/api/user/contact-messages/${messageId}/read`, {
        method: 'PATCH',
        credentials: 'include',
      });
      if (!response.ok) {
        throw new Error('Failed to mark message as read');
      }
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/user/contact-messages'] });
      queryClient.invalidateQueries({ queryKey: ['/api/notifications/unread-count'] });
      toast({
        title: "Message marked as read",
        description: "The message has been marked as read successfully.",
      });
    },
  });

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  const getPriorityColor = (priority: string) => {
    switch (priority.toLowerCase()) {
      case 'high': return 'bg-red-500/20 text-red-400 border-red-500/30';
      case 'medium': return 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30';
      case 'low': return 'bg-green-500/20 text-green-400 border-green-500/30';
      default: return 'bg-gray-500/20 text-gray-400 border-gray-500/30';
    }
  };

  const getCategoryIcon = (category: string) => {
    switch (category.toLowerCase()) {
      case 'technical': return <AlertCircle className="w-4 h-4 text-blue-400" />;
      case 'billing': return <MessageSquare className="w-4 h-4 text-green-400" />;
      case 'general': return <User className="w-4 h-4 text-gray-400" />;
      default: return <MessageSquare className="w-4 h-4 text-gray-400" />;
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-[#0a0a2e] text-white">
        <div className="flex items-center justify-center h-screen">
          <div className="text-center">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-orange-500 mx-auto mb-4"></div>
            <p className="text-gray-300">Loading your messages...</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#0a0a2e] text-white">
      {/* Header */}
      <div className="flex items-center p-3 border-b border-white/10">
        <Link href="/mobile">
          <Button variant="ghost" size="sm" className="mr-2 text-white hover:bg-white/10 p-1">
            <ArrowLeft className="w-4 h-4" />
          </Button>
        </Link>
        <div className="flex-1">
          <h1 className="text-base font-semibold">Messages</h1>
          <p className="text-xs text-gray-400">
            {messages.length} message{messages.length !== 1 ? 's' : ''}
          </p>
        </div>
      </div>

      <div className="flex flex-col lg:flex-row h-[calc(100vh-64px)]">
        {/* Messages List */}
        <div className="w-full lg:w-1/2 border-r border-white/10">
          <ScrollArea className="h-full">
            <div className="p-2 space-y-2">
              {messages.length === 0 ? (
                <div className="text-center py-12">
                  <MessageSquare className="w-16 h-16 text-gray-400 mx-auto mb-4" />
                  <h3 className="text-white text-lg font-medium mb-2">No Messages</h3>
                  <p className="text-gray-300 mb-4">You haven't sent any contact messages yet.</p>
                  <Link href="/company/contact">
                    <Button className="bg-orange-600 hover:bg-orange-700">
                      Send Message
                    </Button>
                  </Link>
                </div>
              ) : (
                messages.map((message: ContactMessage) => (
                  <Card
                    key={message._id}
                    className={`cursor-pointer transition-all duration-200 border-white/20 ${
                      selectedMessage?._id === message._id
                        ? 'bg-orange-500/10 border-orange-500/30'
                        : 'bg-white/5 hover:bg-white/10'
                    }`}
                    onClick={() => setSelectedMessage(message)}
                  >
                    <CardContent className="p-3">
                      <div className="flex items-start justify-between mb-2">
                        <div className="flex items-center space-x-1">
                          {getCategoryIcon(message.category)}
                          <span className="text-gray-300 text-xs capitalize">{message.category}</span>
                        </div>
                        <div className="flex items-center space-x-1">
                          {!message.isRead && (
                            <div className="w-1.5 h-1.5 bg-orange-400 rounded-full"></div>
                          )}
                          <Badge className={`${getPriorityColor(message.priority)} text-xs px-1 py-0`}>
                            {message.priority}
                          </Badge>
                        </div>
                      </div>

                      <div className="text-white text-xs font-medium mb-1 truncate">
                        {message.subject}
                      </div>

                      <div className="text-gray-300 text-xs line-clamp-1 mb-2">
                        {message.message}
                      </div>

                      {message.hasReply && message.adminReply && (
                        <div className="bg-blue-500/10 border border-blue-500/20 rounded-md p-1.5 mb-2">
                          <div className="flex items-center space-x-1 mb-1">
                            <Reply className="w-2.5 h-2.5 text-blue-400" />
                            <span className="text-blue-400 text-xs font-medium">Message from Support</span>
                          </div>
                          <div className="text-gray-300 text-xs line-clamp-1">
                            {message.adminReply}
                          </div>
                        </div>
                      )}

                      <div className="flex items-center justify-between text-xs text-gray-400">
                        <div className="flex items-center space-x-1">
                          <Clock className="w-2.5 h-2.5" />
                          <span className="text-xs">{formatDate(message.createdAt)}</span>
                        </div>
                        {message.hasReply && (
                          <div className="flex items-center space-x-1 text-blue-400">
                            <Reply className="w-2.5 h-2.5" />
                            <span className="text-xs">Replied</span>
                          </div>
                        )}
                      </div>
                    </CardContent>
                  </Card>
                ))
              )}
            </div>
          </ScrollArea>
        </div>

        {/* Message Details */}
        <div className="w-full lg:w-1/2">
          <ScrollArea className="h-full">
            {selectedMessage ? (
              <div className="p-3">
                <Card className="bg-white/5 border-white/20">
                  <CardContent className="p-3">
                    {/* Message Header */}
                    <div className="flex items-start justify-between mb-3">
                      <div className="flex items-center space-x-2">
                        <UserAvatar 
                          user={{
                            profilePicture: selectedMessage.user?.profilePicture,
                            firstName: selectedMessage.firstName,
                            lastName: selectedMessage.lastName,
                            username: selectedMessage.email?.split('@')[0]
                          }}
                          size="sm"
                        />
                        <div>
                          <div className="text-white text-sm font-medium">
                            {selectedMessage.firstName} {selectedMessage.lastName}
                          </div>
                          <div className="text-gray-400 text-xs">{selectedMessage.email}</div>
                        </div>
                      </div>
                      <Badge className={`${getPriorityColor(selectedMessage.priority)} text-xs px-1 py-0`}>
                        {selectedMessage.priority}
                      </Badge>
                    </div>

                    {/* Subject */}
                    <div className="mb-3">
                      <div className="text-gray-300 text-xs mb-1">Subject</div>
                      <div className="text-white text-sm font-medium">{selectedMessage.subject}</div>
                    </div>

                    {/* Original Message */}
                    <div className="mb-4">
                      <div className="text-gray-300 text-xs mb-1">Message</div>
                      <div className="bg-white/5 rounded-md p-2 text-white text-sm whitespace-pre-wrap max-h-24 overflow-y-auto">
                        {selectedMessage.message}
                      </div>
                    </div>

                    {/* Support Reply */}
                    {selectedMessage.hasReply && selectedMessage.adminReply && (
                      <div className="mb-4">
                        <div className="flex items-center space-x-1 mb-1">
                          <Reply className="w-3 h-3 text-blue-400" />
                          <div className="text-blue-400 text-xs font-medium">Message from Support</div>
                          <div className="text-gray-400 text-xs">
                            {selectedMessage.adminReplyAt && formatDate(selectedMessage.adminReplyAt)}
                          </div>
                        </div>
                        <div className="bg-blue-500/10 border border-blue-500/20 rounded-md p-2 text-white text-sm whitespace-pre-wrap max-h-24 overflow-y-auto">
                          {selectedMessage.adminReply}
                        </div>
                      </div>
                    )}

                    {/* Message Info */}
                    <div className="grid grid-cols-2 gap-3 text-xs border-t border-white/20 pt-3">
                      <div>
                        <div className="text-gray-300 mb-1">Category</div>
                        <div className="text-white capitalize">{selectedMessage.category}</div>
                      </div>
                      <div>
                        <div className="text-gray-300 mb-1">Status</div>
                        <div className="flex items-center space-x-1">
                          {selectedMessage.isRead ? (
                            <Eye className="w-4 h-4 text-green-400" />
                          ) : (
                            <EyeOff className="w-4 h-4 text-gray-400" />
                          )}
                          <span className="text-white">
                            {selectedMessage.isRead ? 'Read' : 'Unread'}
                          </span>
                        </div>
                      </div>
                      <div>
                        <div className="text-gray-300 mb-1">Sent</div>
                        <div className="text-white">{formatDate(selectedMessage.createdAt)}</div>
                      </div>
                      <div>
                        <div className="text-gray-300 mb-1">Last Updated</div>
                        <div className="text-white">{formatDate(selectedMessage.updatedAt)}</div>
                      </div>
                    </div>

                    {/* Mark as Read Button */}
                    {!selectedMessage.isRead && (
                      <div className="pt-4 border-t border-white/20 mt-4">
                        <Button
                          onClick={() => markAsReadMutation.mutate(selectedMessage._id)}
                          disabled={markAsReadMutation.isPending}
                          className="bg-blue-600 hover:bg-blue-700"
                        >
                          {markAsReadMutation.isPending ? (
                            <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2" />
                          ) : (
                            <Eye className="w-4 h-4 mr-2" />
                          )}
                          Mark as Read
                        </Button>
                      </div>
                    )}
                  </CardContent>
                </Card>
              </div>
            ) : (
              <div className="flex items-center justify-center h-full">
                <div className="text-center">
                  <MessageSquare className="w-16 h-16 text-gray-400 mx-auto mb-4" />
                  <h3 className="text-white text-lg font-medium mb-2">Select a Message</h3>
                  <p className="text-gray-300">Choose a message from the list to view details</p>
                </div>
              </div>
            )}
          </ScrollArea>
        </div>
      </div>
    </div>
  );
}

