                  Edit Profile
                </Button>
              </Link>
            </div>
          </div>
        </div>

        {/* Menu Content - Fill remaining space and stretch to bottom */}
        <div className="bg-[#0a0a2e] px-4 pt-2 flex-1 flex flex-col">

          {/* Profile Menu Items - Expanding to fill available space */}
